import { test, expect } from '@playwright/test';

test.use({ storageState: '../auth/user.json' });

test.describe('1. Админ-панель — матрица прав и спец. действия', () => {
  test('1.8 Обычный user на /admin перенаправляется, контента панели нет @desktop @prod-safe (#6a8a96c821e5a64ca7a411dd)', async ({ page }) => {
    // 1. Открыть `/admin`.
    await page.goto('/admin');
    await expect(page).not.toHaveURL(/\/admin/);
    test.skip(/\/(welcome|sign-in)/.test(page.url()), 'Сессия user не авторизована (ушло на /welcome или /sign-in): npm run qa-login:manual -- user');
    await expect(page.getByText(/Audit log|יומן ביקורת/)).toHaveCount(0);
    await expect(page.getByRole('table')).toHaveCount(0);

    // 2. Открыть `/admin/users`.
    await page.goto('/admin/users');
    await expect(page).not.toHaveURL(/\/admin/);
    await expect(page.getByText(/Audit log|יומן ביקורת/)).toHaveCount(0);
    await expect(page.getByRole('table')).toHaveCount(0);
  });
});
